// Define the CGAL kernel and Delaunay triangulation types
typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Delaunay_triangulation_2<K> Delaunay;
typedef Delaunay::Point CGALPoint;

// Create the Delaunay triangulation object
Delaunay dt;

// Insert all points into the triangulation
for (const auto& point : points) {
    dt.insert(CGALPoint(point.x(), point.y()));
}

// Convert the CGAL Delaunay triangulation to the required Triangulation2 return type
Triangulation2 result;
for (auto it = dt.finite_faces_begin(); it != dt.finite_faces_end(); ++it) {
    std::array<Point2d, 3> triangle;
    for (int i = 0; i < 3; ++i) {
        auto vertex = it->vertex(i);
        triangle[i] = Point2d(CGAL::to_double(vertex->point().x()),
                             CGAL::to_double(vertex->point().y()));
    }
    result.push_back(triangle);
}

return result;

